head.script:
scwin.fn_GetPar, scwin.fn_SetPar = "";
scwin.gDepCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // round처리
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24701.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    let strCbd = "",
        i, j;

    // 기초지수
    urlBas += "?SCREN_ID=" + "ULDSTF24701.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    urlBas += "&method=listGeneral" + "&outputMessageId=ETN_LSTISUDTLSRCH_OUT_COMBO" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.etn.lstsrch.basIdxCd.list";
    const sbmOptions = {
        id : "sbm_dst_BAS_IDX_CD",
        action : "/listingCommon.do",
        ref : "",
        target : "dst_BAS_IDX_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    strCbd = "^전체";
    cmb_BAS_IDX_CD.CBData = strCbd;
    const arrCid = [{
        cid: "VALU_PRC_CALC_INST_CD",
        cnm: "cmb_VALU_PRC_CALC_INST_CD"
    }, {
        cid: "IDX_CALC_INST_CD",
        cnm: "cmb_IDX_CALC_INST_CD"
    }, {
        cid: "LOSS_LMT_ETN_EARNG_STRUCT_CD",
        cnm: "cmb_EARNG_STRUCT_TP_CD"
    }];
    let objCod;
    const sbmOptions2 = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^전체";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24701.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24701.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24701.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF24701.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        if (dts_List.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd_List, {fileName: "손실제한 ETN 평가 방법론 현황", type: 1}); // show false인것은 안보여준다.(type = 1)

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24701.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF24701.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name cmb_IDX_CALC_INST_CD_onselchange
 * @description cmb_IDX_CALC_INST_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_IDX_CALC_INST_CD_onselchange = function() {
    try {
        scwin.onStepComboSelChange(cmb_IDX_CALC_INST_CD.getValue(), dst_BAS_IDX_CD, cmb_BAS_IDX_CD, "PVALUE");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF24701.cmb_IDX_CALC_INST_CD_onselchange" });
    }
};

/**
 * @method
 * @name cmb_VALU_PRC_CALC_INST_CD_onselchange
 * @description cmb_VALU_PRC_CALC_INST_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_VALU_PRC_CALC_INST_CD_onselchange = function() {

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF24701.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LOSS_LMT_ETN_LSTVALUMETDTHEOSRCH_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.losslmtetn.lstsrch.valu_methd_theo.list" + "&{P}param01=" + cmb_VALU_PRC_CALC_INST_CD.getValue() + "&{P}param02=" + cmb_VALU_PRC_CALC_INST_CD.getValue() + "&{P}param03=" + cmb_EARNG_STRUCT_TP_CD.getValue() + "&{P}param04=" + cmb_EARNG_STRUCT_TP_CD.getValue() + "&{P}param05=" + cmb_IDX_CALC_INST_CD.getValue() + "&{P}param06=" + cmb_IDX_CALC_INST_CD.getValue() + "&{P}param07=" + cmb_BAS_IDX_CD.getValue().substr(1, 6) + // 기초지수idx_mkt_clss_id (6)||idx_seq(3) ||idx_lvrg_invrs_tp_cd (2) = 12
        "&{P}param08=" + cmb_BAS_IDX_CD.getValue().substr(1, 6) + "&{P}param09=" + cmb_BAS_IDX_CD.getValue().substr(7, 3) + "&{P}param10=" + cmb_BAS_IDX_CD.getValue().substr(7, 3) + "&{P}param11=" + cmb_BAS_IDX_CD.getValue().substr(10, 2) + "&{P}param12=" + cmb_BAS_IDX_CD.getValue().substr(10, 2) + "&{P}param13=" + cmb_VALU_PRC_CALC_INST_CD.getValue() + "&{P}param14=" + cmb_VALU_PRC_CALC_INST_CD.getValue() + "&{P}param15=" + cmb_EARNG_STRUCT_TP_CD.getValue() + "&{P}param16=" + cmb_EARNG_STRUCT_TP_CD.getValue() + "&{P}param17=" + cmb_IDX_CALC_INST_CD.getValue() + "&{P}param18=" + cmb_IDX_CALC_INST_CD.getValue() + "&{P}param19=" + cmb_BAS_IDX_CD.getValue().substr(1, 6) + // 기초지수idx_mkt_clss_id (6)||idx_seq(3) ||idx_lvrg_invrs_tp_cd (2) = 12
        "&{P}param20=" + cmb_BAS_IDX_CD.getValue().substr(1, 6) + "&{P}param21=" + cmb_BAS_IDX_CD.getValue().substr(7, 3) + "&{P}param22=" + cmb_BAS_IDX_CD.getValue().substr(7, 3) + "&{P}param23=" + cmb_BAS_IDX_CD.getValue().substr(10, 2) + "&{P}param24=" + cmb_BAS_IDX_CD.getValue().substr(10, 2);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name onStepComboSelChange
 * @description on Step Combo Sel Change 처리
 * @param {*} pValue pValue
 * @param {*} dst dst
 * @param {*} targetObj targetObj
 * @param {String} targetPValueNm targetPValueNm
 * @returns {void}
 * @hidden N
 */
scwin.onStepComboSelChange = function(pValue, dst, targetObj, targetPValueNm) {
    let strCbd = "^전체";
    targetObj.CBData = strCbd;
    if (!(pValue === "" || pValue === null)) {
        for (j = 1; j <= dst.getRowCount(); j++) {
            // alert(dst.NameValue(j, "TEXT")) ;
            if (dst.getCellData(j, targetPValueNm) === pValue) {
                strCbd += (strCbd === "" ? "" : ",") + dst.getCellData(j, "VALUE") + "^" + dst.getCellData(j, "TEXT");
            }
        }
        targetObj.CBData = strCbd;
        targetObj.ResetData();
    }
};
